  'Enable this feature to share my announcements with customers.' => 'Activar this función to share my announcements with clientes.',
  'Select whether your restaurant serves Veg only or both Veg and Non-Veg items.' => 'Seleccionar whether your restaurante serves Vegetariano only or both Vegetariano and Non-Vegetariano artículos.',
  'This section allows the admin to manage order cancellation reasons. Admin can create and configure cancellation reasons based on different user types, control their active status, and mark a reason as default. These reasons will be displayed to users for selection when they attempt to cancel an order.' => 'This sección allows the administrador to administrar cancelación del pedido reasons. Administrador can crear and configurar cancellation reasons based on different usuario types, control their activo estado, and mark a motivo as predeterminado. These reasons will be displayed to usuarios for selection when they attempt to cancelar an pedido.',
  'Set Up Order Cancellation Messages' => 'Configurar Up Cancelación del pedido Mensajes',
  'Configure additional order controls, including enabling the repeat order option for quick reordering, applying delivery verification methods to ensure successful delivery, and selecting the order confirmation model to define how orders are approved and processed within the system.' => 'Configurar additional pedido controls, including enabling the repetir pedido opción for quick reordering, applying entrega verification methods to ensure successful entrega, and selecting the pedido confirmation model to define how pedidos are aprobado and processed within the sistema.',
  'Admin can define the exact dollar amount (USD) that an order must exceed for the customer to receive free shipping automatically.' => 'Administrador can define the exact dollar monto (USD) that an pedido debe exceed for the cliente to recibir gratis shipping automatically.',
  'Free delivery over ($)' => 'Entrega gratis mayor de ($)',
