  'order_unassigned' => 'Pedido unassigned',
  'Cookies Text' => 'Texto de cookies',
  'The Admin Notification Setup allows the administrator to configure how system notifications are sent and managed. Admin notifications can be delivered either manually or through Firebase, depending on the selected configuration.' => 'The Administrador Notificación Configuración allows the administrator to configurar how sistema notificaciones are enviado and managed. Administrador notificaciones can be entregado either manually or through Firebase, depending on the seleccionado configuración.',
  'Cash-in-hand control allows the platform to monitor and limit the amount of cash collected by deliverymen from Cash on Delivery (COD) orders. This feature helps reduce financial risk and ensures timely settlement between the deliveryman and the platform.' => 'Efectivo-in-hand control allows the platform to monitor and límite the monto of efectivo collected by deliverymen from Pago contra entrega (Pago contra entrega) pedidos. This función helps reduce financial risk and ensures timely settlement entre the repartidor and the platform.',
  'Cash-in-Hand Controls' => 'Efectivo-in-Hand Controls',
  'The Deliveryman App Setup feature allows the platform administrator to configure key settings that define how delivery personnel interact with the mobile app., whether deliverymen can view their earnings in the app, and whether capturing a photo is required as delivery proof.' => 'The Repartidor Aplicación Configuración función allows the platform administrator to configurar clave ajustes that define how entrega personnel interact with the móvil aplicación., whether deliverymen can ver their ganancias in the aplicación, and whether capturing a photo es obligatorio as entrega proof.',
