  'Business Setup Guideline' => 'Negocio Configuración Guideline',
  'Turning on Maintenance mode will temporarily close your online store. So that the admin can do important updates or fixes.' => 'Turning on Modo de mantenimiento will temporalmente cerrar your online tienda. So that the administrador can do important updates or fixes.',
  'Company Name' => 'Empresa Nombre',
  'The Company name often serves as the primary identifier for your business as a legal entity.' => 'The Empresa nombre often serves as the primary identifier for your negocio as a legal entity.',
  'A company email system often provides centralised management and archiving of business communication.' => 'A empresa correo sistema often provides centralised gestión and archiving of negocio communication.',
  'A phone number provides customers and partners with a direct and immediate way to reach your business for urgent inquiries, support needs, or quick questions.' => 'A número de teléfono provides clientes and partners with a direct and immediate way to reach your negocio for urgent inquiries, soporte needs, or quick questions.',
  'Country Name field when setting up a business is essential for a multitude of reasons, touching upon legal, operational, financial, and marketing aspects.' => 'País Nombre campo when ajuste up a negocio is essential for a multitude of reasons, touching upon legal, operational, financial, and marketing aspects.',
  'This description is for describing the restaurant business. How vendors interact with the admin to run their business well.' => 'This descripción is for describing the restaurante negocio. How vendors interact with the administrador to run their negocio well.',
  'General Settings' => 'General Ajustes',
  'General Setup is the foundational step, where you configure essential business details to set up the business.' => 'General Configuración is the foundational paso, where you configurar essential negocio detalles to configurar up the negocio.',
  'Allows customers to select the appropriate country code when entering their phone number.' => 'Allows clientes to seleccionar the appropriate país código when entering their número de teléfono.',
  'Subscription-based model' => 'Suscripción-based model',
  'A subscription-based business model allows customers or vendors to access specific features, services, or system functionalities by paying a recurring fee (monthly, quarterly, or yearly). Instead of one-time payments, users remain active as long as their subscription is valid.' => 'A suscripción-based modelo de negocio allows clientes or vendors to access specific features, services, or sistema functionalities by paying a recurring fee (mensual, quarterly, or anual). Instead of one-hora payments, usuarios remain activo as long as their suscripción is valid.',
  'Commission-based model' => 'Comisión-based model',
  'A commission-based business model allows the platform to earn revenue by charging a predefined percentage amount from each successful transaction completed through the system. The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.' => 'A comisión-based modelo de negocio allows the platform to earn revenue by charging a predefined percentage monto from each successful transacción completado through the sistema. The comisión is automatically deducted from the pedido valor before the remaining monto is settled with the tienda or service provider.',
  'Additional Charge Setup' => 'Additional Charge Configuración',
  'The Additional Charge Setup allows the admin to configure extra fees that will be applied to customer orders based on predefined conditions. These charges are added to the order total automatically during checkout and are visible to both customers and vendors.' => 'The Additional Charge Configuración allows the administrador to configurar extra fees that will be applied to cliente pedidos based on predefined conditions. These charges are agregado to the pedido total automatically during checkout and are visible to both clientes and vendors.',
  'Content Setup' => 'Content Configuración',
  'Copyright text' => 'Texto de copyright',
